window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q10"]=window.__LIBQ["the-gioi-hoan-my"]["q10"]||{};window.__LIBQ["the-gioi-hoan-my"]["q10"]["map"]={"updatedAt":"2026-07-24","count":169,"nodes":[{"id":"co-thanh-minh-uoc","name":"Cổ thành Minh Ước","cn":"","capDo":"thanh","parentId":"khu-khong-nguoi","blurb":"Thành cổ được cho là nằm sâu trong khu không người và có thể là điểm đến của Cung điện Chí tôn.","detail":"Cổ tổ của Tuyết Lâm lần theo dấu vết Cung điện Chí tôn và suy đoán cung điện đã hướng tới Cổ thành Minh Ước. Tên thành khiến Thạch Hạo liên tưởng tới Minh ước Thái Cổ và những bí mật liên quan Biên hoang.","theLucLienQuan":["Đạo tràng Chí tôn"],"nguon":["@c0901"]},{"id":"tinh-tho-vung-nui","name":"Tịnh thổ vùng núi","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một vùng núi thanh tịnh được trận pháp che giấu, nơi nhóm Thạch Hạo dùng đoạn tiên thể hỗ trợ tu hành.","detail":"Khu vực có hoa thơm, cỏ lạ, chim hót và khí lành dưới lòng đất. Đả Thần Thạch cùng Tào Vũ Sinh bố trí trận pháp tại đây để ngăn khí tức Tiên đạo tiết ra ngoài.","theLucLienQuan":[],"nguon":["@c0901"]},{"id":"ba-ngan-duong-da","name":"Ba ngàn đường đá","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Nơi Thạch Hạo từng dùng ba ngàn ngọn lửa để rèn luyện con đường tiên khí.","detail":"Thạch Hạo trở lại và khiến cả ba ngàn ngọn lửa đồng thời bùng cháy, bao phủ các đường đá. Sau nhiều ngày tu luyện, hắn xác định nơi này đã đi đến cực hạn và không còn thích hợp để tu ra tia tiên khí thứ hai.","theLucLienQuan":[],"nguon":["@c0901"]},{"id":"minh-tho-co-dia","name":"Minh thổ cổ địa","cn":"","capDo":"khac","parentId":"minh-tho-dia-danh","blurb":"Vùng cổ địa tràn ngập tử khí và minh vụ, nơi Hắc Ám Thần tử triệu tập các cường giả Minh thổ.","detail":"Hắc Ám Thần tử đứng giữa minh vụ trước sự bái kiến của nhiều cường giả Minh thổ và phát lệnh tham gia săn giết Hoang.","theLucLienQuan":["Minh thổ"],"nguon":["@c0901"]},{"id":"han-gioi","name":"Hàn giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Tiểu thiên thế giới lạnh giá trong Tiên cổ, nơi Thạch Hạo chuẩn bị tu luồng tiên khí thứ hai.","detail":"Khí lạnh ở Hàn giới xuyên qua thần lực, xâm nhập xương cốt và hồn phách. Nơi đây có núi tuyết, thi thể thần linh và dấu hiệu liên quan khí tức Tiên đạo.","theLucLienQuan":[],"nguon":["@c0902","@c0984"]},{"id":"trung-tam-co-dia-han-gioi","name":"Trung tâm cổ địa Hàn giới","cn":"","capDo":"vuc","parentId":"han-gioi","blurb":"Vùng núi tuyết rộng lớn ở trung tâm Hàn giới.","detail":"Nơi đây có hoa tuyết và dao băng mang thần lực, đồng thời chôn vùi nhiều thi thể thần linh cùng Chân Thần.","theLucLienQuan":[],"nguon":["@c0902"]},{"id":"bo-lac-sung-ky-lan","name":"Bộ lạc sừng kỳ lân","cn":"","capDo":"khac","parentId":"trung-tam-co-dia-han-gioi","blurb":"Bộ lạc hình người mọc sừng kỳ lân nằm trong núi tuyết.","detail":"Toàn bộ cư dân, gồm người già, trẻ nhỏ và các thiếu nữ trên tế đàn, bị đông chết tức thời trong khi vẫn giữ tư thế và vẻ vui sướng trước đó.","theLucLienQuan":[],"nguon":["@c0902"]},{"id":"bo-lac-co-trong-han-gioi","name":"Bộ lạc cổ trong Hàn giới","cn":"","capDo":"khac","parentId":"han-gioi","blurb":"Một sơn trại mang phong cách Tiên cổ bị băng tuyết phong ấn và bảo tồn hoàn chỉnh. Trong bộ lạc có thảm thực vật đóng băng cùng một tế đàn cổ không còn toàn vẹn.","detail":"Bộ lạc từng có sức sống nhưng toàn bộ sinh linh và cảnh vật đã bị một tai nạn bí ẩn đóng băng. Thạch Hạo, Thái Âm Ngọc Thỏ và Đả Thần Thạch tìm thấy tế đàn cổ tại đây, nơi phát ra khí lạnh chí âm và những dấu ấn liên quan tới Tiên đạo.","theLucLienQuan":[],"nguon":["@c0903"]},{"id":"di-tich-bo-lac-han-gioi","name":"Di tích bộ lạc Hàn giới","cn":"","capDo":"khac","parentId":"han-gioi","blurb":"Di tích của bộ lạc bản địa bị sức mạnh Thái Âm đóng băng tại Hàn giới.","detail":"Nơi đây còn tế đàn lưu giữ hình ảnh người mạnh nhất bộ lạc độ kiếp và chết dưới nguyền rủa. Thạch Hạo cùng Thái Âm Ngọc Thỏ đã mai táng toàn bộ di tích xuống sâu trong lòng đất.","theLucLienQuan":["Bộ lạc Hàn giới"],"nguon":["@c0904"]},{"id":"tieu-the-gioi-u-nguyet","name":"Tiểu thế giới U Nguyệt","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu thế giới nơi Thanh Y và Nguyệt Thiền nhiều lần giao chiến vì vấn đề dung hợp chủ thân và thứ thân.","detail":"Thanh Y và Nguyệt Thiền tiến hành nhiều cuộc giao phong tại đây. Hai người từng tạm thời dung hợp nhưng lại tách ra vì cùng muốn giữ dấu ấn và quyền chủ đạo của mình.","theLucLienQuan":[],"nguon":["@c0905"]},{"id":"day-nui-tuyet-han-gioi","name":"Dãy núi tuyết Hàn giới","cn":"","capDo":"khac","parentId":"han-gioi","blurb":"Dãy núi lạnh giá còn lưu khí tức Tiên đạo, nơi Thạch Hạo dùng đạo hỏa thiêu luyện bản thân.","detail":"Đạo hỏa làm băng tuyết và phù văn lạnh buốt trên núi tan chảy, nhưng khí tức Tiên đạo khiến chúng liên tục tái hiện. Nơi này cũng được cho là có thể chôn giấu di vật của người từng suýt thành Tiên.","theLucLienQuan":[],"nguon":["@c0905"]},{"id":"day-nui-nhieu-mau-o-han-gioi","name":"Dãy núi nhiều màu ở Hàn giới","cn":"","capDo":"vuc","parentId":"han-gioi","blurb":"Dãy núi rộng lớn tại Hàn giới, có nhiều vùng thực vật mang màu sắc khác nhau.","detail":"Dãy núi có những ngọn phủ đào tuyết trắng xóa và những ngọn mọc Hoàng kim bách vàng rực. Nguyệt Thiền đưa Thạch Hạo đi sâu vào khu vực này để tìm nơi giam giữ.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0906"]},{"id":"dong-phu-co-tai-han-gioi","name":"Động phủ cổ tại Hàn giới","cn":"","capDo":"khac","parentId":"day-nui-nhieu-mau-o-han-gioi","blurb":"Động phủ của tu sĩ đời trước được Nguyệt Thiền chọn làm nơi giam giữ Thạch Hạo.","detail":"Động phủ nằm dưới chân một ngọn núi cổ. Trận pháp bên ngoài đã hư hại sau thời gian dài, nhưng bên trong vẫn sạch sẽ, có giường đá, tĩnh thất và linh khí nồng đậm.","theLucLienQuan":["Bổ Thiên giáo"],"nguon":["@c0906"]},{"id":"day-nui-dao-tuyet-va-hoang-kim-bach","name":"Dãy núi đào tuyết và hoàng kim bách","cn":"","capDo":"vuc","parentId":"han-gioi","blurb":"Khu vực Nguyệt Thiền chọn để dựng bẫy và giả tạo hiện trường giao chiến.","detail":"Nguyệt Thiền bố trí dấu vết giao chiến trong động phủ và ngoài dãy núi để khiến Thanh Y tin rằng nàng cùng Thạch Hạo đều bị trọng thương.","theLucLienQuan":[],"nguon":["@c0907"]},{"id":"thuc-hai","name":"Thức hải","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian ý thức nơi cánh cửa vàng, nguồn hồn lực và cô gái bí ẩn được nhìn thấy.","detail":"Cuộc chiến nguyên thần giữa Thanh Y và Nguyệt Thiền diễn ra trong thức hải, nơi một cánh cửa vàng che giấu nguồn hồn lực đang ngủ say.","theLucLienQuan":[],"nguon":["@c0908"]},{"id":"ky-nguyen-tien-co","name":"Kỷ nguyên Tiên cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Thời đại được nhắc đến như nguồn gốc của Thanh Nguyệt tiên tử và Thanh Nguyệt diễm.","detail":"Thanh Nguyệt diễm và dấu ấn tiên chủng được Thanh Nguyệt tiên tử lưu lại từ kỷ nguyên Tiên cổ.","theLucLienQuan":[],"nguon":["@c0908"]},{"id":"dong-phu","name":"Động phủ","cn":"","capDo":"khac","parentId":null,"blurb":"Động phủ là nơi diễn ra cuộc quyết đấu giữa Nguyệt Thiền và Thanh Y.","detail":"Thạch Hạo bị đánh văng vào vách động trong cuộc tranh đấu. Sau khi thân thể chung phân tách, Thanh Y ở lại còn Nguyệt Thiền chạy ra khỏi động phủ.","theLucLienQuan":[],"nguon":["@c0909"]},{"id":"day-nui-co-dong-phu-co","name":"Dãy núi có động phủ cổ","cn":"","capDo":"khac","parentId":"han-gioi","blurb":"Dãy núi trong Hàn giới lưu lại dấu vết chiến đấu và bao quanh động phủ cổ.","detail":"Thỏ nhỏ và Đả Thần Thạch lần theo dấu vết chiến đấu tới khu vực này. Thạch Hạo và Thanh Y ẩn náu trong động phủ cổ tại đây.","theLucLienQuan":[],"nguon":["@c0910"]},{"id":"loan-gioi","name":"Loan giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Khu vực được đồn từng xuất hiện Trường Sinh dược.","detail":"Nguyệt Thiền ở trong một vùng tịnh thổ có ôn tuyền tại Loan giới.","theLucLienQuan":[],"nguon":["@c0911"]},{"id":"trach-gioi","name":"Trạch giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Thế giới có nhiều ao hồ và đầm nước.","detail":"Thanh Y ngâm mình trong một hồ lớn ở Trạch giới.","theLucLienQuan":[],"nguon":["@c0911"]},{"id":"con-gioi","name":"Côn giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nơi Thạch Hạo gặp lại nhóm Lạc Đạo.","detail":"Thạch Hạo dùng thiên nhãn phát hiện Lạc Đạo, Lam Nhất Trần và Lộ Dịch tại Côn giới.","theLucLienQuan":[],"nguon":["@c0911"]},{"id":"nguyen-gioi","name":"Nguyên giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một địa điểm Thạch Hạo đi qua sau khi xuất quan.","detail":"Thạch Hạo lần lượt tìm kiếm đồng bạn qua Nguyên giới.","theLucLienQuan":[],"nguon":["@c0911"]},{"id":"vung-ven-khu-khong-nguoi","name":"Vùng ven khu không người","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực bên ngoài nơi các giáo chủ quan sát tình hình.","detail":"Các giáo chủ quan sát tình hình qua cánh hoa tiên đạo ở vùng ven khu không người.","theLucLienQuan":[],"nguon":["@c0911"]},{"id":"kim-linh-gioi","name":"Kim Linh giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Kim Linh giới là một tiểu thiên thế giới đặc biệt, nơi Tuyết Lâm bị Cổ Mông truy sát.","detail":"Khắp nơi trong Kim Linh giới là những ngọn núi bằng kim loại nhô khỏi mặt đất, hầu như không có cỏ và bề mặt kim loại bóng lưỡng. Tuyết Lâm trốn vào đây sau khi bị phục kích, còn Cổ Mông, Quân Đạo và Hắc Ám Thần tử đều xuất hiện tại nơi này.","theLucLienQuan":["Thần miếu","Thiên quốc","Minh thổ"],"nguon":["@c0912","@c0913"]},{"id":"thanh-vu-thanh","name":"Thanh Vũ thành","cn":"","capDo":"thanh","parentId":null,"blurb":"Thanh Vũ thành là nơi có Hắc Ám thần cung bị Thạch Hạo phá hủy.","detail":"Thạch Hạo phá nổ tung Hắc Ám thần cung tại Thanh Vũ thành và diệt toàn bộ nhân mã Minh tộc.","theLucLienQuan":["Minh tộc","Minh thổ"],"nguon":["@c0912"]},{"id":"vo-tri-gioi","name":"Vô Trì giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Vô Trì giới là nơi có một cứ điểm bí mật của Thần miếu.","detail":"Thạch Hạo dùng Tiên kiếm Đại La bổ đôi nơi bí mật của Thần miếu tại Vô Trì giới.","theLucLienQuan":["Thần miếu"],"nguon":["@c0912"]},{"id":"xich-viem-gioi","name":"Xích Viêm giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Xích Viêm giới là địa bàn của Nham Ma tộc.","detail":"Nham Ma tộc đóng tại Xích Viêm giới và bị Thạch Hạo giết sạch trong cuộc càn quét.","theLucLienQuan":["Nham Ma tộc","Thiên quốc"],"nguon":["@c0912"]},{"id":"day-nui","name":"Dãy núi","cn":"","capDo":"vuc","parentId":"kim-linh-gioi","blurb":"Khu vực núi nơi Thạch Hạo truy kích Cổ Mông.","detail":"Thạch Hạo lao xuống dãy núi khi truy kích Cổ Mông và tiếp cận Tuyết Lâm.","theLucLienQuan":[],"nguon":["@c0913"]},{"id":"hu-khong-chien-truong","name":"Hư không chiến trường","cn":"","capDo":"khac","parentId":null,"blurb":"Hư không chiến trường là khu vực diễn ra trận chiến giữa Thạch Hạo và Hắc Ám Thần tử.","detail":"Kiếm lô, Đọa Hồn thuật và các bảo thuật lan ra trong khu vực này, khiến nhiều tu sĩ quan chiến rơi xuống hoặc bị thương.","theLucLienQuan":[],"nguon":["@c0915"]},{"id":"chien-truong-tien-co","name":"Chiến trường Tiên Cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Không gian giao chiến giữa Thạch Hạo với Hắc Ám Thần tử, Cổ Thánh tử và quái thai cổ đại của Thiên quốc.","detail":"Chiến trường bị kiếm khí, núi phù văn, bàn tay thần thông và uy lực của Đỉnh tiên kim hắc ám liên tục phá hủy; hư không nhiều lần sụp đổ trong cuộc hỗn chiến.","theLucLienQuan":["Minh thổ","Thiên quốc"],"nguon":["@c0916"]},{"id":"tien-duoc-vien-co-xua","name":"Tiên dược viên cổ xưa","cn":"","capDo":"gioi-nho","parentId":"kim-linh-gioi","blurb":"Một dược viên cổ xưa phiêu lưu trong hư không và chỉ thỉnh thoảng hiện thế. Nơi này chứa vô số dược thảo thần thánh cùng dấu hiệu của Trường Sinh dược.","detail":"Tiên dược viên xuất hiện trong không gian loạn lưu sau khi đại trận phong tỏa và hư không quanh chiến trường bị phá vỡ. Dược viên được truyền là đã phiêu lưu trong hư không hơn một kỷ nguyên, rất khó tìm kiếm và chứa nhiều cơ duyên khiến cường giả các tộc đồng loạt tranh đoạt.","theLucLienQuan":["Thiên quốc","Cổ Thánh tộc"],"nguon":["@c0917"]},{"id":"khong-gian-loan-luu","name":"Không gian loạn lưu","cn":"","capDo":"khac","parentId":"kim-linh-gioi","blurb":"Khu vực hư không hỗn loạn nơi Tiên dược viên cổ xưa hiện ra. Nhiều cường giả tiến vào đây để tiếp cận dược viên.","detail":"Sau khi trận pháp phong tỏa bị hủy và hư không vỡ nát, Tiên dược viên hiện ra trong vùng không gian loạn lưu. Quái thai cổ đại của Thiên quốc, Cổ Thánh tử, Thạch Hạo và cường giả các tộc lần lượt xông vào khu vực này.","theLucLienQuan":["Thiên quốc","Cổ Thánh tộc"],"nguon":["@c0917"]},{"id":"hon-dao-duoc-vien","name":"Hòn đảo dược viên","cn":"","capDo":"khac","parentId":"tien-duoc-vien-co-xua","blurb":"Hòn đảo dược viên nổi giữa dòng chảy không gian và là nơi Thạch Hạo cùng Đả Thần Thạch đặt chân tới.","detail":"Trên đảo có cỏ cây rực rỡ, linh khí và khí lành dày đặc, cùng nhiều thánh dược và cổ mộc thần thánh.","theLucLienQuan":[],"nguon":["@c0918"]},{"id":"vet-rach-hu-khong-lon","name":"Vết rách hư không lớn","cn":"","capDo":"khac","parentId":null,"blurb":"Vết rách hư không lớn là khu vực dẫn vào dược viên cổ và chứa các đợt Hư không đại liệt trảm nguy hiểm.","detail":"Khu vực có nhiều vết rách ẩn trong hư không, nơi loạn lưu có thể bùng nổ và chém chết cả Chân Thần.","theLucLienQuan":[],"nguon":["@c0918"]},{"id":"khong-gian-thu-nguyen","name":"Không gian thứ nguyên","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian thứ nguyên là nguồn sức mạnh được phun trào để duy trì phong tỏa quanh hòn đảo dược viên.","detail":"Sức mạnh từ không gian thứ nguyên được dùng để hình thành hoặc duy trì bố trí phong tỏa quanh dược viên.","theLucLienQuan":[],"nguon":["@c0918"]},{"id":"vach-da-tren-hon-dao","name":"Vách đá trên hòn đảo","cn":"","capDo":"khac","parentId":"hon-dao-duoc-vien","blurb":"Vách đá trên hòn đảo là nơi xuất hiện một tổ cổ mang dị tượng phượng hoàng và khí tức Hoàng huyết.","detail":"Một tổ cổ được bố trí vững vàng trên vách đá, xung quanh có bóng phượng hoàng lượn quanh và khí tức Hoàng huyết lan tỏa.","theLucLienQuan":[],"nguon":["@c0918"]},{"id":"phuong-hoang-sao","name":"Phượng Hoàng sào","cn":"","capDo":"khac","parentId":"tien-duoc-vien-co-xua","blurb":"Cổ sào nằm trên đỉnh Ngọn núi đổ trong Tiên dược viên cổ.","detail":"Bên trong Phượng Hoàng sào có đạo đài năm màu, Hoàng Huyết thạch, thánh dược và truyền thừa liên quan tới Hoàng tộc.","theLucLienQuan":[],"nguon":["@c0919"]},{"id":"duoc-dao","name":"Dược đảo","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Hòn đảo thần bí tập trung nhiều linh dược, di tích và trận pháp Tiên đạo.","detail":"Dược đảo có nhiều khu vực nguy hiểm được trận pháp Tiên đạo bảo vệ, trong khi linh thảo bản địa có thể ra vào. Hòn đảo chỉ hiện ra bên ngoài trong thời gian ngắn rồi có thể ẩn vào hư không loạn lưu.","theLucLienQuan":[],"nguon":["@c0920"]},{"id":"hoang-sao","name":"Hoàng sào","cn":"","capDo":"khac","parentId":"duoc-dao","blurb":"Khu vực phủ đầy phù văn đặc biệt, nơi Tuyết Lâm ở lại bế quan.","detail":"Hoàng sào gắn với huyết thống Hoàng tộc, khiến người không có huyết thống tương ứng khó tiến vào an toàn. Tuyết Lâm ở lại đây trong lúc Thạch Hạo và Đả Thần Thạch tiến sâu vào dược đảo.","theLucLienQuan":[],"nguon":["@c0920"]},{"id":"suoi-tien","name":"Suối tiên","cn":"","capDo":"khac","parentId":"duoc-dao","blurb":"Nơi sinh linh được Hắc Hâm gọi là đại nhân đang chờ gặp Thạch Hạo.","detail":"Hắc Hâm truyền lời rằng chủ nhân của nó đang ở suối tiên và muốn mời Thạch Hạo tới gặp mặt nói chuyện.","theLucLienQuan":[],"nguon":["@c0920"]},{"id":"khu-co-dia-trong-duoc-dao","name":"Khu cổ địa trong dược đảo","cn":"","capDo":"khac","parentId":"duoc-dao","blurb":"Vùng di tích cổ phủ sương mù hỗn độn, chứa dấu tích của sức mạnh Tiên đạo đáng sợ.","detail":"Khu cổ địa có kiến trúc đổ nát, tiếng cổ thú vang động, tiên khí và kiếm khí đủ hủy diệt tiểu thiên thế giới. Hắc Hâm dẫn Thạch Hạo cùng Đả Thần Thạch tới đây để gặp sinh linh ẩn trong sương trắng.","theLucLienQuan":[],"nguon":["@c0920"]},{"id":"hon-dao-bi-phong-an","name":"Hòn đảo bị phong ấn","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo bị phong ấn là nơi Bạch Quy và khu dược bị giam cầm qua hơn một kỷ nguyên.","detail":"Hòn đảo bị ngăn cách với ánh mặt trời bởi phong ấn. Bạch Quy nhờ Thạch Hạo phá giải phong ấn để có cơ hội rời khỏi nơi này.","theLucLienQuan":[],"nguon":["@c0921"]},{"id":"bat-lao-tuyen","name":"Bất Lão tuyền","cn":"","capDo":"khac","parentId":"hon-dao-bi-phong-an","blurb":"Bất Lão tuyền là một đầm nước nằm phía sau Vạn Vật thổ, bên dưới có kim liên quang minh.","detail":"Đầm nước không lớn nhưng đủ cho nhiều người tiến vào, một giọt nước có thể cứu một mạng. Dưới đáy Bất Lão tuyền có sợi kim liên chứa tiên kim quang minh.","theLucLienQuan":[],"nguon":["@c0921"]},{"id":"nhan-tien-dien","name":"Nhân Tiên điện","cn":"","capDo":"khac","parentId":null,"blurb":"Nhân Tiên điện là nơi Bạch Quy đề nghị đưa Thạch Hạo tới để tìm thêm cơ duyên.","detail":"Bạch Quy cho rằng nếu Thạch Hạo đến được Nhân Tiên điện, vận may của hắn sẽ lớn hơn và có thể tìm được hướng xử lý vấn đề tu luyện tia tiên khí thứ hai.","theLucLienQuan":[],"nguon":["@c0921"]},{"id":"duoc-vien-co","name":"Dược viên cổ","cn":"","capDo":"khac","parentId":"duoc-dao","blurb":"Hòn đảo chứa nhiều dược thảo cùng các khu vực ẩn trong không gian khác.","detail":"Dược viên cổ được bảo vệ bởi bố cục trận pháp phức tạp. Bạch Quy thông thạo các khu vực và đường hầm hư không trong đảo, có thể dẫn người tiến vào những nơi ẩn chứa huyền cơ.","theLucLienQuan":[],"nguon":["@c0922"]},{"id":"khu-co-dia","name":"Khu cổ địa","cn":"","capDo":"khac","parentId":"duoc-vien-co","blurb":"Vùng đất yên tĩnh không có cỏ cây, nằm sau các đường hầm hư không.","detail":"Khu cổ địa nằm trên đường tiến đến Nhân Tiên điện, sau các đường hầm hư không và trước dãy thạch lâm. Nơi đây không có cây cỏ, mang vẻ tĩnh lặng và cổ xưa.","theLucLienQuan":[],"nguon":["@c0922"]},{"id":"thach-dien","name":"Thạch điện","cn":"","capDo":"khac","parentId":"nhan-tien-dien","blurb":"Phòng đá bề ngoài đơn sơ nhưng bên trong rộng lớn, lưu giữ các tranh đá và những cửa ải nguy hiểm.","detail":"Thạch điện có không gian bên trong lớn hơn vẻ ngoài. Các tranh đá mô tả nhiều cảnh tượng cổ xưa, đồng thời có thể phát động những thử thách đủ sức sát hại người vượt ải thất bại.","theLucLienQuan":[],"nguon":["@c0922"]},{"id":"dia-phuong-truong-sinh-that-su","name":"Địa phương trường sinh thật sự","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi được cho là có thể tránh khỏi sự thoái hóa của thượng giới.","detail":"Địa phương trường sinh thật sự nằm bên ngoài thượng giới theo lời Bạch Quy. Người chưa thành tiên không biết phương pháp tìm đến nơi này.","theLucLienQuan":[],"nguon":["@c0922"]},{"id":"thach-dien-thi-luyen","name":"Thạch điện thí luyện","cn":"","capDo":"khac","parentId":"nhan-tien-dien","blurb":"Thạch điện có các hình khắc sinh linh và phát động những thử thách chí mạng.","detail":"Thạch điện là nơi Thạch Hạo trải qua các cửa ải về nguyên thần, đạo chủng và những thử thách nguy hiểm khác.","theLucLienQuan":["Nhân Tiên điện"],"nguon":["@c0923"]},{"id":"mat-that-be-quan-nhan-tien-dien","name":"Mật thất bế quan Nhân Tiên điện","cn":"","capDo":"khac","parentId":"nhan-tien-dien","blurb":"Mật thất cuối cùng cho phép người bế quan thức tỉnh lại nhiều lần trong quá trình ngộ đạo.","detail":"Mật thất rộng khoảng mười trượng, có thể giam cầm các mảnh vỡ thời gian và cho phép người bế quan thức tỉnh lại tối đa mười lần dù tẩu hỏa nhập ma hoặc chết.","theLucLienQuan":["Nhân Tiên điện"],"nguon":["@c0923"]},{"id":"co-quang-thien-nhan-toc","name":"Cổ quáng Thiên Nhân tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Cổ quáng nơi Thạch Hạo từng thu được tiên chủng Vạn Vật mẫu khí.","detail":"Thạch Hạo từng đoạt tiên chủng hình quả trứng chứa Vạn Vật mẫu khí tại cổ quáng của Thiên Nhân tộc.","theLucLienQuan":["Thiên Nhân tộc"],"nguon":["@c0923"]},{"id":"mat-that-muoi-truong","name":"Mật thất mười trượng","cn":"","capDo":"khac","parentId":"thach-dien","blurb":"Mật thất mười trượng là không gian tu luyện nằm trong thạch điện, nơi Thạch Hạo và Tiểu Tiên vương từng dùng vạn đạo để rèn luyện.","detail":"Mật thất có vách đá xù xì, thời gian bên trong biến đổi khác với ngoại giới và lưu lại hình ảnh tu luyện của Tiểu Tiên vương từ kỷ nguyên trước.","theLucLienQuan":[],"nguon":["@c0924"]},{"id":"chien-truong-cuoi-ky-nguyen-tien-co","name":"Chiến trường cuối kỷ nguyên Tiên cổ","cn":"","capDo":"khac","parentId":"chien-truong-tien-co","blurb":"Chiến trường cuối kỷ nguyên Tiên cổ là nơi phụ thân của Tiểu Tiên vương chết trận.","detail":"Đây cũng là đích đến mà Tiểu Tiên vương muốn bước tới để tiếp nối phụ thân và chiến đấu cho tới khi kỷ nguyên kết thúc.","theLucLienQuan":[],"nguon":["@c0924"]},{"id":"nha-da-luyen-duoc","name":"Nhà đá luyện dược","cn":"","capDo":"khac","parentId":null,"blurb":"Gian nhà đá phía sau cánh cửa ánh sáng thứ hai, lưu giữ tinh hoa dược tính trên vách đá.","detail":"Trong nhà đá luyện dược có tinh hoa dược tính tồn lưu trên vách cùng hình ảnh thân thể Tiểu Tiên vương được đưa vào sau khi ngộ đạo thất bại và tử vong.","theLucLienQuan":[],"nguon":["@c0925"]},{"id":"hon-dao-co-duoc-vien","name":"Hòn đảo cổ dược viên","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Cổ địa chứa thần dược, cổ trận và Chân Hoàng sào.","detail":"Hòn đảo sắp tiến vào hư không loạn lưu rồi biến mất, có thể xé giới bích tới cố hương của Tiên hoặc trôi vào khu vực không người ở ngoại giới.","theLucLienQuan":[],"nguon":["@c0926"]},{"id":"den-da-va-mat-that-muoi-truong","name":"Đền đá và mật thất mười trượng","cn":"","capDo":"khac","parentId":"hon-dao-co-duoc-vien","blurb":"Nơi Thạch Hạo từng tọa quan và gặp dấu tích của tiểu Tiên vương.","detail":"Thạch Hạo từ bỏ ý định bế quan tại đền đá vì hòn đảo sắp biến mất.","theLucLienQuan":[],"nguon":["@c0926"]},{"id":"co-huong-cua-tien","name":"Cố hương của Tiên","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Nơi được Bạch Quy nhắc đến như một địa phương có thể tồn tại trường sinh.","detail":"Bạch Quy nói nơi này có những nhân vật cực mạnh nhưng không biết vị trí cụ thể.","theLucLienQuan":[],"nguon":["@c0926"]},{"id":"chien-truong-menh-mong","name":"Chiến trường mênh mông","cn":"","capDo":"khac","parentId":null,"blurb":"Chiến trường mà tiểu Tiên vương từng muốn tiến vào.","detail":"Đây là nơi những người mạnh nhất và có tiềm lực nhất được kỳ vọng tham dự để xoay chuyển càn khôn.","theLucLienQuan":[],"nguon":["@c0926"]},{"id":"khu-vuc-mep-dao","name":"Khu vực mép đảo","cn":"","capDo":"khac","parentId":"hon-dao-co-duoc-vien","blurb":"Vùng rìa nơi các cường giả chỉ có thể hái dược.","detail":"Những người không vượt qua được cổ trận chỉ có thể hoạt động ở khu vực mép đảo, không thể tiến vào khu trung tâm.","theLucLienQuan":[],"nguon":["@c0926"]},{"id":"khu-vuc-khong-nguoi-rong-lon-ngoai-gioi","name":"Khu vực không người rộng lớn ở ngoại giới","cn":"","capDo":"vuc","parentId":null,"blurb":"Một điểm đến nguy hiểm mà đảo cổ có thể trôi tới sau khi biến mất.","detail":"Bạch Quy dự đoán hòn đảo có thể bị đưa vào khu vực không người ở ngoại giới sau khi xuyên qua hư không loạn lưu.","theLucLienQuan":[],"nguon":["@c0926"]},{"id":"tieu-the-gioi-khong-ro-ten","name":"Tiểu thế giới không rõ tên","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nơi Thạch Hạo lựa chọn để bế quan.","detail":"Thạch Hạo dựng đại trận, bố trí hậu chiêu nghi binh và bắt đầu luyện đạo hỏa tại tiểu thế giới này.","theLucLienQuan":[],"nguon":["@c0927"]},{"id":"bo-lac-trong-day-nui-co","name":"Bộ lạc trong dãy núi cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Khu dân bản địa có cung điện đồng.","detail":"Đây là nơi Đế Côn cư trú và tiếp Quái thai cổ đại của Thiên quốc.","theLucLienQuan":["bo-lac-dan-ban-dia-trong-day-nui-co"],"nguon":["@c0927"]},{"id":"dong-phu-trong-long-nui","name":"Động phủ trong lòng núi","cn":"","capDo":"khac","parentId":"tieu-the-gioi-khong-ro-ten","blurb":"Động phủ trong dãy núi nơi Thạch Hạo bế quan và dùng vạn Đạo nung luyện thân thể cùng nguyên thần.","detail":"Khu vực quanh động phủ được Đả Thần Thạch bố trí nhiều sát trận liên kết thành tuyệt địa. Thạch Hạo trải qua nhiều lần cận tử tại đây trong quá trình ngưng tụ luồng tiên khí thứ hai.","theLucLienQuan":[],"nguon":["@c0928"]},{"id":"nha-giam-hac-am","name":"Nhà giam hắc ám","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian đen tối trong hư vô nơi nguyên thần Thạch Hạo bị phong kín sau khi luồng tiên khí thứ hai thành hình.","detail":"Nhà giam trôi trong dòng sông thời gian và ngăn nguyên thần Thạch Hạo trở về thể xác. Hắn còn nhìn thấy nhiều nhà giam tương tự, bên trong phong ấn những sinh linh cổ xưa có khí tức và cảnh giới vượt xa mình.","theLucLienQuan":[],"nguon":["@c0928"]},{"id":"nha-giam-hu-vo-u-toi","name":"Nhà giam hư vô u tối","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian lạnh lẽo và u tối giam giữ nguyên thần Thạch Hạo.","detail":"Bóng tối trong nhà giam liên tục ăn mòn hồn lực và tạo cảm giác thời gian kéo dài hàng trăm, hàng nghìn hoặc hàng vạn năm. Bên trong vẫn tồn tại hồn lực có thể được khí tức Tiên đạo hấp thu.","theLucLienQuan":[],"nguon":["@c0929"]},{"id":"dong-song-thoi-gian","name":"Dòng sông thời gian","cn":"","capDo":"khac","parentId":null,"blurb":"Dòng sông thời gian hiện ra sau khi Thạch Hạo đánh xuyên nhà giam hư vô.","detail":"Bên ngoài lỗ thủng có dòng sông thời gian, nơi nhiều nhà giam u tối khác đang bồng bềnh.","theLucLienQuan":[],"nguon":["@c0929"]},{"id":"long-nui","name":"Lòng núi","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi thân thể Thạch Hạo đang ngồi giữa các trận pháp.","detail":"Quân Đạo, vương giả Thiên quốc và Cổ Thánh tử của Thần miếu nhờ đại sư trận pháp bản địa phá đường tiến vào lòng núi.","theLucLienQuan":["Thiên quốc","Thần miếu"],"nguon":["@c0929"]},{"id":"luyen-duoc-dien","name":"Luyện dược điện","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi thân thể của Tiểu Tiên vương từng được đưa tới sau thất bại.","detail":"Thân thể Tiểu Tiên vương được đưa vào Luyện dược điện trong khi nguyên thần đã mất tích.","theLucLienQuan":[],"nguon":["@c0929"]},{"id":"cuu-thien","name":"Cửu thiên","cn":"","capDo":"vuc","parentId":null,"blurb":"Phạm vi được nhắc đến cùng Cửu u trong khả năng xuyên thấu của chân kinh gọi hồn.","detail":"Âm thanh và ký hiệu gọi hồn của Cổ Thánh tử được nói đến trong phạm vi Cửu thiên và Cửu u.","theLucLienQuan":[],"nguon":["@c0930"]},{"id":"cuu-u","name":"Cửu u","cn":"","capDo":"vuc","parentId":null,"blurb":"Phạm vi được nhắc cùng Cửu thiên trong khả năng xuyên thấu của chân kinh gọi hồn.","detail":"Cửu u được nhắc đến như một nơi mà âm thanh và ký hiệu của Cửu thiên thập địa kinh có thể xuyên tới.","theLucLienQuan":[],"nguon":["@c0930"]},{"id":"nha-giam-u-toi","name":"Nhà giam u tối","cn":"","capDo":"khac","parentId":null,"blurb":"Nhà giam u tối là một nơi gắn với lần lột xác đầu tiên của Luân Hồi quyền.","detail":"Thạch Hạo từng trải qua nơi này trước khi Luân Hồi quyền hoàn thành bước lột xác đầu tiên.","theLucLienQuan":[],"nguon":["@c0932"]},{"id":"tieu-thien-the-gioi","name":"Tiểu Thiên Thế Giới","capDo":"gioi-nho","parentId":"tien-co","blurb":"Không gian nhỏ nằm trong di tích Tiên cổ, nơi tiếng sáo của Trích Tiên vang vọng tạo cảnh tượng vạn hoa nở và chim muông bay múa.","detail":"Tiểu Thiên Thế Giới là các không gian nằm trong di tích Tiên cổ. Việc Thạch Hạo tu thành luồng tiên khí thứ hai được dự đoán sẽ truyền khắp di tích và khiến cường giả ở nhiều Tiểu Thiên Thế Giới biết đến.","theLucLienQuan":[],"nguon":["@c0933"]},{"id":"hoang-kim-dao-cung","name":"Hoàng Kim Đạo cung","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Cổ cung còn có tên là cung điện Tiếp Dẫn, thuộc kỷ nguyên trước và mang khí tức Tiên Đạo. Sự xuất hiện của nó báo hiệu võ đài Tiên Đạo cùng cuộc tranh bá cuối cùng của Tiên cổ đang tới gần.","detail":"Hoàng Kim Đạo cung có mái ngói vàng, một phần vẫn vùi trong hư vô và chứa truyền thừa cùng binh khí Tiên cổ. Cổ cung đôi khi phóng cổ bảo ra ngoài nên các vương giả cổ đại liên tục truy đuổi và dùng nhiều thủ đoạn giao cảm. Sau khi tiếp nhận nguyên thần hình hài trẻ nhỏ, cung điện biến mất hoàn toàn cùng võ đài Tiên Đạo.","theLucLienQuan":[],"nguon":["@c0934"]},{"id":"vo-dai-tien-dao","name":"Võ đài Tiên Đạo","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Võ đài cổ dành cho cuộc tranh bá cuối cùng giữa những kỳ tài mạnh nhất trong Tiên cổ.","detail":"Hình bóng mơ hồ của võ đài xuất hiện bên cạnh cung điện Tiếp Dẫn. Đây được xem là chiến trường cuối cùng của cuộc tranh hùng, có khả năng truyền tống người chiến thắng đi nhận vận may cuối cùng; ngay sau khi thoáng hiện, võ đài biến mất cùng cổ cung.","theLucLienQuan":[],"nguon":["@c0934"]},{"id":"di-chi-thanh-co-duoi-long-dat","name":"Di chỉ thành cổ dưới lòng đất","cn":"","capDo":"khac","parentId":"dai-thao-nguyen-hoa-chau","blurb":"Di chỉ dưới lòng đất là nơi Thạch Hạo tìm được Thần phù bảo vệ và Phá Giới phù.","detail":"Nơi đây từng xảy ra vụ nổ đủ sức xuyên thủng Hộp báu bằng đồng.","theLucLienQuan":[],"nguon":["@c0935"]},{"id":"nha-giam-trong-bong-toi","name":"Nhà giam trong bóng tối","cn":"","capDo":"khac","parentId":null,"blurb":"Nhà giam trong bóng tối là không gian chứa hồn lực, nơi Thạch Hạo từng tu hành.","detail":"Quá trình tu hành tại đây khiến nguyên thần lực của Thạch Hạo tăng mạnh, đủ để gắng gượng chống lại uy thế thần thức của Thiên Thần.","theLucLienQuan":[],"nguon":["@c0935"]},{"id":"nhan-ma-toc","name":"Nhân Mã tộc","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Địa bàn nơi nhóm Thỏ nhỏ tu hành trong Tiên cổ.","detail":"Từ nơi này, nhóm Thỏ nhỏ thỉnh cầu và thuyết phục các cường giả dân bản địa ra tay cứu viện Thạch Hạo.","theLucLienQuan":["Nhân Mã tộc"],"nguon":["@c0937"]},{"id":"tieu-thien-the-gioi-thien-than-doi-dau","name":"Tiểu thiên thế giới nơi các Thiên Thần đối đầu","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thiên thế giới có quần sơn, núi rừng và cổ mộc, nơi phe bảo vệ Hoang đối đầu các Thiên Thần săn bắt.","detail":"Thần uy trong cuộc giao phong giữa Thiên Thần tuyệt đỉnh Bát Tí Hồn tộc và voi vàng phá hủy cảnh vật xung quanh. Phe săn bắt sau đó rút khỏi nơi này khi hóa thân cấp Giáo chủ xuất hiện.","theLucLienQuan":["Bát Tí Hồn tộc","Cổ Ma tộc","Nhân Mã tộc","Hoàng kim cự tượng tộc","Cầu Long tộc"],"nguon":["@c0938"]},{"id":"bo-lac-nhan-ma-toc","name":"Bộ lạc Nhân Mã tộc","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Địa bàn của Nhân Mã tộc, nơi Thạch Hạo từng định tới nhờ lão tộc trưởng bảo vệ và chữa thương.","detail":"Thạch Hạo từ bỏ kế hoạch tới bộ lạc sau khi bị một Thiên Thần Nhân Mã tộc giả vờ tiếp đón rồi dùng cung bắn lén từ cách vùng đất cổ hàng ngàn dặm.","theLucLienQuan":["Nhân Mã tộc"],"nguon":["@c0938"]},{"id":"day-nui-hoang-vu","name":"Dãy núi hoang vu","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng núi nhiều cây cỏ và lão dược, nơi Thạch Hạo tạm ẩn náu sau khi thoát khỏi Nhân Mã tộc.","detail":"Thạch Hạo ẩn trong một tổ kim ưng giữa vùng núi, dùng lão dược cùng thịt ba con Ngạc Long cấp Chân Thần nấu dược thực để chữa Đạo thương.","theLucLienQuan":[],"nguon":["@c0939"]},{"id":"hac-uyen","name":"Hắc uyên","cn":"","capDo":"khac","parentId":"tang-thanh","blurb":"Vực sâu trong Táng thành lưu giữ nhiều dấu tích cổ xưa và là nguồn phát tán khói đen cùng nguyền rủa.","detail":"Hắc uyên sâu mười vạn trượng, có dấu tích chiến đấu của Tiên, cành cây Liễu Thần, máu Côn Bằng, mảnh lông Phượng Hoàng và tế đàn cổ. Khói đen từ vực sâu bùng lên khiến ba Thiên Thần trúng nguyền rủa, gây thương vong cho dân bản địa Tiên cổ và làm Táng thành đại loạn.","theLucLienQuan":["Dân bản địa Tiên cổ"],"nguon":["@c0939"]},{"id":"am-gioi","name":"Ám giới","cn":"","capDo":"gioi-nho","parentId":"tieu-thien-the-gioi","blurb":"Một Tiểu Thiên Thế Giới rộng lớn bị nguyền rủa nghiêm trọng, nơi các sinh linh đều bị ma hóa và mất thần trí.","detail":"Ám giới có nhiều chủng tộc nhưng phần lớn chỉ còn bản năng vì ảnh hưởng của nguyền rủa. Ngay cả Thiên Thần trong giới này cũng thường ngủ đông và có thể gây bạo động nếu bị quấy nhiễu, khiến những người truy sát Thạch Hạo phải dè chừng.","theLucLienQuan":[],"nguon":["@c0940","@c0945","@c0946"]},{"id":"hon-don-van-ho","name":"Hỗn Độn Văn hồ","cn":"","capDo":"khac","parentId":"am-gioi","blurb":"Hồ nước đen kịt nằm trong Ám giới, chứa sát khí, nguyền rủa và đàn muỗi ma hóa cực kỳ nguy hiểm.","detail":"Sát khí quanh hồ sắc bén như dao, đủ khiến chân thân Thiên Thần của Đế Côn phải dừng bước. Trong hồ có muỗi màu mã não đạt Thần Hỏa cảnh, hàng vạn muỗi bạc đạt Chân Thần cảnh, muỗi vàng mang khí tức Thiên Thần và hai con muỗi nhỏ tỏa khí hỗn độn còn đáng sợ hơn toàn bộ đàn muỗi trước đó.","theLucLienQuan":[],"nguon":["@c0940","@c0941","@c0942","@c0943"]},{"id":"day-hon-don-van-ho","name":"Đáy Hỗn Độn Văn hồ","cn":"","capDo":"khac","parentId":"hon-don-van-ho","blurb":"Đáy hồ là nơi Thạch Hạo dưỡng thương, phát hiện tinh khí đặc biệt và tiếp tục thăm dò.","detail":"Sau khi lặn xuống khoảng bốn mươi ngàn trượng, Thạch Hạo nhìn thấy ánh sáng cùng cảnh tượng có rồng và một người phụ nữ bí ẩn.","theLucLienQuan":[],"nguon":["@c0941"]},{"id":"tien-duoc-vien","name":"Tiên Dược viên","cn":"","capDo":"vuc","parentId":null,"blurb":"Nơi Thạch Hạo từng nghe Bạch Quy đề cập đến khả năng thiên kiếp tạo ra luồng tiên khí thứ ba.","detail":"Tiên Dược viên được nhắc lại trong suy nghĩ của Thạch Hạo khi hắn cân nhắc việc chủ động dẫn thiên kiếp.","theLucLienQuan":[],"nguon":["@c0942"]},{"id":"day-ho","name":"Đáy hồ","cn":"","capDo":"khac","parentId":"hon-don-van-ho","blurb":"Khu vực dưới đáy Văn hồ hỗn độn, nơi cô gái bí ẩn và Chân Long cốt hiện diện.","detail":"Thạch Hạo bị lực lượng quanh cô gái đánh bật khi tiến vào khu vực này, sau đó nhiều lần đến gần để hấp thu khí tức sinh mệnh chữa thương.","theLucLienQuan":[],"nguon":["@c0942"]},{"id":"bach-cot-son","name":"Bạch Cốt sơn","cn":"","capDo":"vuc","parentId":null,"blurb":"Nơi Minh chủ đứng quan sát diễn biến và nổi giận vì Minh tộc bị sỉ nhục.","detail":"Minh chủ đứng trên Bạch Cốt sơn theo dõi sự việc trong Tiên cổ.","theLucLienQuan":["Minh tộc"],"nguon":["@c0944"]},{"id":"bien-gioi-khu-vuc-khong-nguoi-rong-lon","name":"Biên giới khu vực không người rộng lớn","cn":"","capDo":"vuc","parentId":"bien-gioi-khu-vuc-khong-nguoi","blurb":"Nơi chủ nhân Ma Quỳ viên theo dõi sự việc và đánh nát một ngọn núi trong cơn giận.","detail":"Các tu sĩ ngoại giới theo dõi diễn biến tại khu vực này, nơi chủ nhân Ma Quỳ viên trút giận.","theLucLienQuan":["Ma Quỳ viên"],"nguon":["@c0944"]},{"id":"ho-hon-don-van","name":"Hồ Hỗn Độn Văn","cn":"","capDo":"khac","parentId":"tieu-thien-the-gioi","blurb":"Hồ nước đen chứa nhiều sinh linh nguy hiểm trong Tiên cổ.","detail":"Hồ Hỗn Độn Văn nằm trong Tiểu thiên thế giới, chứa vô số muỗi thần, ấu trùng Chân Thần và những sinh linh mang hình thái cổ văn hỗn độn. Thạch Hạo lợi dụng nơi này để đánh tan cuộc vây giết của các Thiên Thần.","theLucLienQuan":["Thiên Thần"],"nguon":["@c0945"]},{"id":"ho-nuoc-den","name":"Hồ nước đen","cn":"","capDo":"khac","parentId":null,"blurb":"Hồ nước đen chứa đàn muỗi và hai Hỗn độn cổ văn.","detail":"Hồ bị pháp tắc Thiên Thần làm sôi trào và thiêu khô một phần trước khi trở lại ổn định.","theLucLienQuan":[],"nguon":["@c0946"]},{"id":"son-mach-bi-phong-toa","name":"Sơn mạch bị phong tỏa","cn":"","capDo":"vuc","parentId":null,"blurb":"Sơn mạch bị các Thiên Thần giam cầm hư không.","detail":"Các Thiên Thần phong tỏa sơn mạch trong giai đoạn đầu cuộc vây sát Thạch Hạo.","theLucLienQuan":["Các Thiên Thần vây sát Hoang"],"nguon":["@c0946"]},{"id":"khu-vuc-thien-kiep","name":"Khu vực thiên kiếp","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng không gian bị hai con Hỗn độn cổ văn niêm phong, nơi thiên kiếp và nguyền rủa giáng xuống.","detail":"Khu vực thiên kiếp bị Hỗn độn cổ văn phong tỏa. Thiên kiếp mãnh liệt cùng nguyền rủa đậm đặc khiến núi sông nổ nát và hư không tan vỡ, đồng thời ngăn các Thiên Thần tìm đường chạy trốn.","theLucLienQuan":[],"nguon":["@c0947"]},{"id":"vung-dat-co-cua-ty-huu-toc","name":"Vùng đất cổ của Tỳ Hưu tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng đất đầy loạn thạch nơi Tỳ Hưu tộc cư trú.","detail":"Tỳ Hưu trở về vùng đất cổ này nhưng không tiến sâu vào nơi cư trú vì nguyền rủa trên thân thể có thể lan sang bộ tộc.","theLucLienQuan":["Tỳ Hưu tộc"],"nguon":["@c0948"]},{"id":"vien-son","name":"Viên sơn","cn":"","capDo":"vuc","parentId":null,"blurb":"Quần thể núi rộng lớn nối tiếp nhau, là nơi Viên tộc sinh sống.","detail":"Cổ viên trở về bên ngoài Viên sơn sau khi phá vòng vây nhưng không tiến vào để tránh nguyền rủa lan sang bộ tộc.","theLucLienQuan":["Viên tộc"],"nguon":["@c0948"]},{"id":"cung-dien-co-bang-dong-cua-de-con","name":"Cung điện cổ bằng đồng của Đế Côn","cn":"","capDo":"khac","parentId":null,"blurb":"Kiến trúc bằng đồng nằm trong vùng đất cổ, nơi Đế Côn chống lại nguyền rủa.","detail":"Đế Côn ngồi trong cung điện cổ bằng đồng để chống lại nguyền rủa trước khi đối đầu với Thạch Hạo.","theLucLienQuan":["Tiên điện"],"nguon":["@c0948"]},{"id":"bien-sam","name":"Biển sấm","cn":"","capDo":"vuc","parentId":null,"blurb":"Biển sấm là khu vực thiên kiếp vô tận bao phủ Thạch Hạo.","detail":"Biển sấm thai nghén Thao Thiết lôi điện, Thiên bia và Đại đạo Trát đao trong quá trình Thạch Hạo độ kiếp.","theLucLienQuan":[],"nguon":["@c0949"]},{"id":"loi-vuc-muoi-tang","name":"Lôi vực mười tầng","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Khu vực thiên kiếp gồm nhiều tầng trời và các cửa ải lôi kiếp.","detail":"Lôi vực có chiến trường loạn quân, tầng cổ bảo, vùng nhà giam nguyên thần và tầng thứ mười chứa cổ dược, sinh linh mang tiên khí cùng Trảm Tiên đài.","theLucLienQuan":[],"nguon":["@c0950"]},{"id":"tien-canh-loi-kiep","name":"Tiên cảnh lôi kiếp","cn":"","capDo":"gioi-nho","parentId":"loi-vuc-muoi-tang","blurb":"Tầng trời có cảnh vật giống tiên cảnh nhưng được tạo thành từ phù văn lôi kiếp.","detail":"Nơi đây có hoa cỏ, chim hót, đình đài và tiên khí trắng; toàn bộ cảnh vật thực chất do phù văn lôi kiếp hóa thành.","theLucLienQuan":[],"nguon":["@c0950"]},{"id":"nha-giam-mau-den-trong-dong-song-thoi-gian","name":"Nhà giam màu đen trong dòng sông thời gian","cn":"","capDo":"khac","parentId":"loi-vuc-muoi-tang","blurb":"Không gian tối tăm chứa những nhà giam dọc theo dòng sông thời gian.","detail":"Những nhà giam màu đen giam giữ nguyên thần của các cường giả. Thạch Hạo rời thân thể và chiến đấu giữa các mảnh vỡ thời gian tại đây.","theLucLienQuan":[],"nguon":["@c0950"]},{"id":"tram-tien-dai","name":"Trảm Tiên đài","cn":"","capDo":"khac","parentId":"loi-vuc-muoi-tang","blurb":"Cổ đài ở tầng thứ mười của lôi vực, phát ra tiên quang có uy lực trảm tiên.","detail":"Tiên quang từ Trảm Tiên đài nhiều lần đánh nát thân thể Thạch Hạo. Hắn sống sót vì cổ đài không thực sự nhằm trực tiếp vào mình.","theLucLienQuan":[],"nguon":["@c0950"]},{"id":"ao-vang-loi-kiep-dich","name":"Ao vàng Lôi Kiếp dịch","cn":"","capDo":"khac","parentId":"loi-vuc-muoi-tang","blurb":"Ao vàng nhỏ chứa Lôi Kiếp dịch và một cây thần thụ màu vàng cổ xưa.","detail":"Ao rộng không quá nửa mét vuông, nằm ở cuối lôi vực. Thạch Hạo kiệt sức bò tới và uống Lôi Kiếp dịch trong ao.","theLucLienQuan":[],"nguon":["@c0950"]},{"id":"khu-vuc-thu-muoi-cua-thien-kiep","name":"Khu vực thứ mười của thiên kiếp","cn":"","capDo":"khac","parentId":"bien-sam","blurb":"Tầng cao nhất nằm phía trên biển sấm chín tầng trời, nơi Thạch Hạo hoàn tất quá trình tiến hóa sau khi trở thành Chân Thần.","detail":"Khu vực này hiện ra cảnh tượng như tiên gia với đình đài, núi cao, thánh dược, chim thần và tiên thú. Lôi đình còn sót lại có thể tự phản kích người ngoài can dự thiên kiếp, phá hủy binh khí và giết các Chân Thần chưa tu ra tiên khí.","theLucLienQuan":[],"nguon":["@c0951"]},{"id":"bien-sam-chin-tang-troi","name":"Biển sấm chín tầng trời","cn":"","capDo":"khac","parentId":"bien-sam","blurb":"Thiên kiếp gồm chín tầng mà Thạch Hạo liên tiếp vượt qua trước khi tiến vào khu vực thứ mười.","detail":"Sau khi Thạch Hạo vượt qua chín tầng, biển sấm còn sót lại vẫn phản ứng với công kích từ bên ngoài. Lôi đình men theo quỹ tích của những đòn tập kích để phản sát người can dự.","theLucLienQuan":[],"nguon":["@c0951"]},{"id":"te-linh-gioi","name":"Tế Linh giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Tịnh thổ nằm trong di địa Tiên cổ, được mười bộ lạc lớn bảo vệ.","detail":"Tế Linh giới có linh khí hóa lỏng, thần sơn lơ lửng, thác nước vàng, hồ nước thần thánh và những miếu thờ cổ đã sụp đổ. Khu vực trung tâm là cấm địa lưu giữ dấu tích cùng pháp tướng của Liễu Thần.","theLucLienQuan":["Bát Tí Hồn tộc","Mười bộ lạc Tế Linh giới"],"nguon":["@c0953"]},{"id":"thanh-dia-te-linh","name":"Thánh địa Tế Linh","cn":"","capDo":"khac","parentId":"te-linh-gioi","blurb":"Khu vực trung tâm và cấm địa của Tế Linh giới.","detail":"Thạch Hạo được các Thiên Thần dẫn vào thánh địa vì nơi đây còn lưu giữ một cành cây của Tế Linh. Trong khu vực có hồ nước, miếu thờ cổ và những dấu tích về việc vô số sinh linh thờ phụng cây Liễu.","theLucLienQuan":["Bát Tí Hồn tộc","Mười bộ lạc Tế Linh giới"],"nguon":["@c0953"]},{"id":"ho-nuoc-trong-te-linh-gioi","name":"Hồ nước trong Tế Linh giới","cn":"","capDo":"khac","parentId":"thanh-dia-te-linh","blurb":"Hồ nước thần thánh ở trung tâm Tế Linh giới, nơi pháp tướng Liễu Thần hiện ra.","detail":"Các dòng sông linh lực hội tụ về hồ. Pháp tướng cây Liễu khổng lồ cắm rễ tại đây và hiện thân trước Thạch Hạo cùng các Thiên Thần hộ tống.","theLucLienQuan":["Mười bộ lạc Tế Linh giới"],"nguon":["@c0953"]},{"id":"trung-tam-co-dia-ba-ngan-chau","name":"Trung tâm cổ địa ba ngàn châu","cn":"","capDo":"khac","parentId":"ba-ngan-chau","blurb":"Cổ địa ở trung tâm ba ngàn châu, nơi đặt tế đàn do nhiều giáo cùng cai quản.","detail":"Một tia điện bạc từ vực ngoại giáng xuống cổ địa và đánh thức tế đàn cùng Tiên đạo tàn trận, khiến các Giáo chủ lo ngại sinh linh ngoài thế giới sắp giáng lâm.","theLucLienQuan":["Các giáo ở ba ngàn châu"],"nguon":["@c0953"]},{"id":"mieu-co","name":"Miếu cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi cành cây vàng của Liễu Thần tồn tại và trò chuyện với Thạch Hạo.","detail":"Trước miếu cổ, Thạch Hạo gặp cành cây Liễu Thần, được giải đáp về người bí ẩn họ Diệp, định hướng con đường Chân Nhất và tiếp nhận cổ thuật của Liễu Thần.","theLucLienQuan":["Tế Linh"],"nguon":["@c0954"]},{"id":"trung-chau","name":"Trung châu","cn":"","capDo":"chau","parentId":"thuong-gioi","blurb":"Khu vực trung tâm của thượng giới, nơi tế đàn cổ và tàn trận Tiên đạo thức tỉnh.","detail":"Ánh điện bạc từ tế đàn nối trời đất rồi ngưng tụ thành cánh cửa thông đạo. Ba người trung niên cùng nhóm nam nữ trẻ tuổi bí ẩn bước ra tại đây, khiến các đại giáo và cường giả thượng giới tập trung quan sát.","theLucLienQuan":["Bổ Thiên giáo","Các đại giáo thượng giới"],"nguon":["@c0954"]},{"id":"hon-dao","name":"Hồn đảo","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Bảo địa và cấm địa của Bát Tí Hồn tộc, là một cổ đảo lớn lơ lửng giữa không trung. Khu vực phía trước an lành, còn vùng núi đá phía sau bị khói đen bao phủ vì giam giữ lão tổ phát cuồng.","detail":"Hồn đảo có núi đẹp, thần tuyền, vườn thuốc và chim thần tại khu vực tiếp khách. Phía sau đảo là vùng núi đá không có cây cỏ, phủ khói đen và đặt đại trận giam lão tổ Bát Tí Hồn tộc.","theLucLienQuan":["Bát Tí Hồn tộc"],"nguon":["@c0955"]},{"id":"to-dia-te-linh","name":"Tổ địa Tế linh","cn":"","capDo":"khac","parentId":"te-linh-gioi","blurb":"Tổ địa của Tế Linh, nơi đoàn Thạch Hạo rời khỏi trước khi tới Hồn đảo dự tiệc mừng.","detail":"Sau khi rời tổ địa Tế Linh, Thạch Hạo cùng các Thiên Thần và đồng bạn tới bảo địa của Bát Tí Hồn tộc.","theLucLienQuan":["Mười bộ lạc Tế Linh giới"],"nguon":["@c0955"]},{"id":"vuon-thuoc-co-hon-toc","name":"Vườn thuốc cổ Hồn tộc","cn":"","capDo":"khac","parentId":"hon-dao","blurb":"Vườn dược nằm trên Hồn đảo, chứa nhiều dược thảo quý và cả thần dược đã thành tinh.","detail":"Thiên Thần Bát Tí Hồn tộc cho phép Thỏ nhỏ lấy nửa lá từ mỗi cây thuốc. Tại đây, nàng phát hiện một cây thần dược có linh tính và cắn mất một góc lá của nó.","theLucLienQuan":["Bát Tí Hồn tộc"],"nguon":["@c0955"]},{"id":"khu-nui-da-phia-sau-hon-dao","name":"Khu núi đá phía sau Hồn đảo","cn":"","capDo":"khac","parentId":"hon-dao","blurb":"Vùng núi đá hoang vu phía sau Hồn đảo, hoàn toàn đối lập với cảnh quan an lành ở mặt trước. Nơi này phủ khói đen và có đại trận giam lão tổ Bát Tí Hồn tộc.","detail":"Khu vực không có cây cỏ, bị khói đen bao phủ do ảnh hưởng từ lão tổ đang chịu nguyền rủa. Những sợi xích lớn và đại trận được bố trí tại đây để cố định cường giả khi ông phát cuồng.","theLucLienQuan":["Bát Tí Hồn tộc"],"nguon":["@c0955"]},{"id":"co-dia-te-linh","name":"Cổ địa Tế linh","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Cổ địa Tế linh là nơi đệ nhất cao thủ Bát Tí Hồn tộc tiếp tục tự phong ấn sau khi nhận Lôi Kiếp dịch.","detail":"Thạch Hạo từng sử dụng Lôi Kiếp dịch tại đây, yêu cầu các tộc giữ kín bí mật rồi rời đi. Nơi này cũng tiếp nhận tin tức về kết quả độ kiếp của Cô Kiếm Vân.","theLucLienQuan":["Bát Tí Hồn tộc"],"nguon":["@c0956"]},{"id":"di-dia-tien-co","name":"Di địa Tiên cổ","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Di địa Tiên cổ là nơi diễn ra các lần độ kiếp và cuộc tranh giành Lôi Kiếp dịch.","detail":"Nhiều Thiên Thần tại di địa Tiên cổ tìm cách tiếp cận Cô Kiếm Vân sau khi hắn vượt qua thiên kiếp.","theLucLienQuan":["Nhân Mã tộc","Cổ Ma tộc","Kiếm cốc"],"nguon":["@c0956"]},{"id":"dao-cung-vang","name":"Đạo cung vàng","cn":"","capDo":"khac","parentId":"van-gioi","blurb":"Đạo cung vàng, còn gọi là Cổ điện tiếp đón, xuất hiện từ hư không tại Vân giới.","detail":"Cung điện cổ có mái ngói vàng, phù điêu và cột trụ khổng lồ. Sự xuất hiện của nó báo hiệu võ đài chung cực sắp mở.","theLucLienQuan":[],"nguon":["@c0957"]},{"id":"vo-dai-tien-co","name":"Võ đài Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Võ đài cổ xưa nổi giữa không trung, là chiến trường dành cho tuyệt thế thiên tài.","detail":"Võ đài được xây bằng nham thạch thần bí, phủ đầy vết máu và mảnh binh khí vỡ. Nơi đây từng chứng kiến nhiều cường giả và quái thai cổ đại tử chiến.","theLucLienQuan":[],"nguon":["@c0957"]},{"id":"di-tich-tien-co-bi-nguyen-rua","name":"Di tích Tiên cổ bị nguyền rủa","cn":"","capDo":"di-tich","parentId":"tien-co","blurb":"Di tích Tiên cổ nơi Ninh Xuyên tiến vào biển sấm để độ kiếp.","detail":"Đây là vùng đất khiến dân bản địa sợ hãi tránh xa; trong di tích, hàng trăm nghìn tia lôi điện giáng xuống.","theLucLienQuan":[],"nguon":["@c0957"]},{"id":"tu-vong-hai","name":"Tử Vong hải","cn":"","capDo":"vuc","parentId":"tien-co","blurb":"Biển nước màu đen nơi Thập Quan vương dẫn phát thiên phạt.","detail":"Tử Vong hải được xem là vùng đất không ai dám tiến vào, nhưng Thập Quan vương đã độ kiếp tại đây.","theLucLienQuan":[],"nguon":["@c0957"]},{"id":"van-gioi","name":"Vân giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Vân giới là tiểu thế giới nơi Đạo cung vàng và võ đài Tiên đạo mở ra.","detail":"Vân giới thu hút thiên tài ngoại giới cùng dân bản địa khi Đạo cung vàng và võ đài Tiên đạo xuất hiện.","theLucLienQuan":[],"nguon":["@c0959"]},{"id":"vo-dai-tranh-ba-tien-co","name":"Võ đài tranh bá Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Võ đài cổ xưa đứng sừng sững trong hư không, là nơi diễn ra các trận tranh bá.","detail":"Võ đài không bị hủy bởi các trận chiến cấp Chân Thần và người không thuộc địa Tiên cổ không thể tùy ý lên đài.","theLucLienQuan":[],"nguon":["@c0960"]},{"id":"khe-lon-cua-di-dia-tien-co","name":"Khe lớn của di địa Tiên cổ","cn":"","capDo":"khac","parentId":"trung-chau","blurb":"Một khe lớn thuộc di địa Tiên cổ, đang bị đông đảo Giáo chủ tập trung công kích.","detail":"Trong biến cố tại Trung châu, khoảng một nửa số Giáo chủ của các đại giáo tập trung công kích địa điểm này.","theLucLienQuan":["Các đại giáo tại ba ngàn châu"],"nguon":["@c0962"]},{"id":"tran-phap-tien-dao","name":"Trận pháp Tiên đạo","cn":"","capDo":"khac","parentId":"trung-chau","blurb":"Một trận pháp tại Trung châu, nơi nhiều Giáo chủ tập trung trong biến cố ngoại giới.","detail":"Đây là nơi người trẻ tuổi đến từ Thiên thắng liên tiếp tám mươi mốt trận trước các Thiên Thần và công khai thách tất cả cùng tiến lên.","theLucLienQuan":["Các đại giáo tại ba ngàn châu","Thiên Thần"],"nguon":["@c0962"]},{"id":"thien","name":"Thiên","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Nơi người trẻ tuổi ngoại lai tự nhận xuất thân, được phân biệt với Địa và nằm ngoài thượng giới hiện tại.","detail":"Chương này chỉ xác nhận Thiên là nơi xuất thân theo lời người trẻ tuổi đã áp đảo các Thiên Thần tại Trung châu; bản chất và phạm vi cụ thể của địa vực chưa được giải thích.","theLucLienQuan":[],"nguon":["@c0962"]},{"id":"vo-dai-co-than-bi","name":"Võ đài cổ thần bí","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Võ đài nơi Thạch Hạo liên tục thủ đài và đạt tám trăm trận thắng. Nơi này chưa công nhận hắn là người thắng cuối cùng vì vẫn còn nhiều người muốn khiêu chiến.","detail":"Võ đài từng có thể công nhận người thắng cuối cùng trước khi toàn bộ cuộc tranh bá kết thúc. Dù Thạch Hạo đã vượt kỷ lục hơn bảy trăm trận của một quái thai cổ đại, lần này võ đài vẫn không đưa ra phán quyết vì số người khiêu chiến chưa dứt.","theLucLienQuan":["Các đại giáo tại ba ngàn châu","Bộ tộc Ngân Huyết ma thụ","Ma Quỳ viên","Minh thổ","Thiên quốc"],"nguon":["@c0963"]},{"id":"tien-co","name":"Tiên cổ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian diễn ra cuộc tranh bá và chuỗi thủ đài của Thạch Hạo. Dân bản địa bị võ đài hạn chế khi giao chiến với người ngoại lai trên đài.","detail":"Sau khi Thạch Hạo rời võ đài, di dân Tiên cổ vẫn có thể trực tiếp khiêu chiến hắn, tạo điều kiện cho các phe thù địch tiếp tục cuộc vây công.","theLucLienQuan":["Bát Tí Hồn tộc","Hậu nhân và bộ lạc của bảy đại Thiên Thần"],"nguon":["@c0963"]},{"id":"gioi-bich-tien-co","name":"Giới bích Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Ranh giới ngăn cách tiểu thế giới Tiên cổ với ngoại giới. Nhiều cường giả đang công kích nơi này nhằm phá giới tiến vào.","detail":"Các đợt công kích từ ngoại giới khiến những vết rách hư không khắp Tiên cổ rung chuyển dữ dội. Di dân Tiên cổ lo ngại các Giáo chủ sẽ tiến vào và phá vỡ sự yên tĩnh đã tồn tại vô tận năm tháng.","theLucLienQuan":["Các đại giáo tại ba ngàn châu"],"nguon":["@c0965"]},{"id":"canh-cua-anh-sang","name":"Cánh cửa ánh sáng","cn":"","aliases":[],"capDo":"khac","parentId":"vo-dai-co-than-bi","blurb":"Một truyền tống trận hình thành trên võ đài và liên tục phát ra lực hút kéo Thạch Hạo vào trong.","detail":"Cánh cửa ánh sáng bành trướng khi võ đài bắt đầu bốc cháy và giải thể. Thạch Hạo lợi dụng lực kéo của nó, chặt đứt sự trói buộc từ pháp tắc Thế Giới thụ rồi tiến vào trong và biến mất khỏi chiến trường.","theLucLienQuan":[],"nguon":["@c0970"]},{"id":"huyen-minh-gioi","name":"Huyền Minh giới","cn":"","capDo":"gioi-nho","parentId":"tien-co","blurb":"Một tiểu thiên thế giới trở thành điểm nối giữa Tiên cổ và ngoại giới.","detail":"Khe nứt không gian tại Huyền Minh giới được dùng làm lối thử tiến vào Tiên cổ. Một chuẩn Giáo chủ đã bị quy tắc Tiên cổ giết chết tại đây, qua đó xác nhận người vượt lĩnh vực Thiên Thần không thể xâm nhập.","theLucLienQuan":["Người ngoại giới"],"nguon":["@c0971"]},{"id":"vung-dat-cuoi-phia-sau-canh-cua-anh-sang","name":"Vùng đất cuối phía sau cánh cửa ánh sáng","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Khu vực thần bí nằm sau cánh cửa ánh sáng trong Tiên cổ.","detail":"Thạch Hạo đã tới nơi này trước những người tiến vào sau. Cuối chương, hắn đứng một mình quan sát vùng đất thần bí và dường như hóa đá.","theLucLienQuan":[],"nguon":["@c0971"]},{"id":"vung-dat-tao-hoa-tien-co","name":"Vùng đất tạo hóa Tiên cổ","cn":"","aliases":["Vùng đất tạo hóa"],"capDo":"gioi-nho","parentId":"tien-co","blurb":"Khu vực thần bí lưu giữ tàn cảnh về thất bại của thời đại Tiên cổ và con đường dẫn tới tạo hóa phía sau.","detail":"Nơi này ban đầu tràn ngập hoa tiên, thánh quang và tiên khí, sau đó hiện ra vô số tàn cảnh chiến tranh, thi thể cường giả cùng một đại lục tan rã. Cảnh tượng thần thánh dần suy tàn, để lộ bức tường tuyệt vọng và con đường dẫn lên chín tầng trời.","theLucLienQuan":[],"nguon":["@c0972"]},{"id":"buc-tuong-tuyet-vong","name":"Bức tường tuyệt vọng","cn":"","capDo":"khac","parentId":"vung-dat-tao-hoa-tien-co","blurb":"Vách tường tối tăm chắn đường tiến sâu vào vùng đất tạo hóa Tiên cổ.","detail":"Bức tường mang những hình chạm khắc mơ hồ về sự tuyệt vọng của Tiên cổ. Sau khi Thạch Hạo dùng ba luồng tiên khí, nhiều bảo thuật và Lục Hợp thiên công công kích, nó mở ra một cánh cửa hình người.","theLucLienQuan":[],"nguon":["@c0972"]},{"id":"cau-thang-tinh-khong","name":"Cầu thang tinh không","cn":"","capDo":"khac","parentId":"vung-dat-tao-hoa-tien-co","blurb":"Cầu thang trong hư vô được ghép từ những ngôi sao đã qua luyện chế và thu nhỏ.","detail":"Mỗi bậc cầu thang gồm chín ngôi sao ghép lại. Con đường đi xuyên qua hư vô, tinh không và những cơn gió có thể phá tan các ngôi sao, cuối cùng dẫn tới chín tầng trời.","theLucLienQuan":[],"nguon":["@c0972"]},{"id":"chin-tang-troi","name":"Chín tầng trời","cn":"","capDo":"vuc","parentId":"vung-dat-tao-hoa-tien-co","blurb":"Khu vực phía trên cầu thang tinh không, mang hình dáng một nghĩa địa cổ rộng lớn.","detail":"Nơi đây không có cung điện huy hoàng hay Tiên nhân mà chỉ có vùng đất đỏ sẫm phủ đầy những gò mộ lớn. Bên dưới các gò mộ là cung điện dưới lòng đất với nhiều quan tài ngọc cổ.","theLucLienQuan":[],"nguon":["@c0972"]},{"id":"khu-truyen-thua-quan-tai-co","name":"Khu truyền thừa quan tài cổ","cn":"","capDo":"khac","parentId":"vung-dat-tao-hoa-tien-co","blurb":"Khu vực lưu giữ hàng chục đến gần một trăm quan tài ngọc thuộc truyền thừa từ hơn một kỷ nguyên trước.","detail":"Trong các quan tài, thi thể không đầu biến mất và được thay bằng Đạo thư ngọc thạch cùng tiên chủng. Những quan tài có bí lực bảo vệ khiến Thạch Hạo không thể mở nắp để lấy truyền thừa.","theLucLienQuan":[],"nguon":["@c0973"]},{"id":"chiec-thuyen-lon-den-nhuom-mau","name":"Chiếc thuyền lớn đen nhuốm máu","cn":"","capDo":"khac","parentId":null,"blurb":"Con thuyền đen nhuốm máu mà Thạch Hạo từng xông vào, bên trong có một chiếc đỉnh đá chứa đầu lâu của những cường giả vô thượng.","detail":"Khi nhìn thấy các thi thể không đầu trong quan tài cổ, Thạch Hạo nhớ lại những đầu lâu trên con thuyền và nghi ngờ hai cảnh tượng có liên quan, nhưng chưa xác định được nguồn gốc chung.","theLucLienQuan":[],"nguon":["@c0973"]},{"id":"khu-vuc-mo-tien","name":"Khu vực mộ Tiên","cn":"","capDo":"khac","parentId":"di-dia-tien-co","blurb":"Khu vực nằm trên hành trình từ cung điện dưới lòng đất trở lại bức tường tuyệt vọng.","detail":"Thạch Hạo rời cung điện dưới lòng đất, vượt qua khu vực mộ Tiên rồi trở lại con đường không gian màu vàng để phục kích những người mang tạo hóa.","theLucLienQuan":[],"nguon":["@c0975"]},{"id":"con-duong-khong-gian-mau-vang","name":"Con đường không gian màu vàng","cn":"","capDo":"khac","parentId":"di-dia-tien-co","blurb":"Lối đi không gian duy nhất dùng để trở về từ khu vực tạo hóa.","detail":"Con đường không có truyền tống trận và đi qua bức tường tuyệt vọng. Thạch Hạo khoét một chỗ lõm trên vách tường gần đường đi để ẩn nấp phục kích.","theLucLienQuan":[],"nguon":["@c0975"]},{"id":"tieu-thien-the-gioi-co-vo-dai","name":"Tiểu thiên thế giới có võ đài","cn":"","capDo":"gioi-nho","parentId":"di-dia-tien-co","blurb":"Tiểu thiên thế giới chứa võ đài và những vật tạo hóa được các tu sĩ trẻ tranh đoạt.","detail":"Thạch Hạo, Diệp Thiên Vũ và Thập Quan vương lần lượt rời khỏi nơi này mang theo thu hoạch, sau đó bị lực lượng Thiên Thần phong tỏa tại võ đài bên ngoài.","theLucLienQuan":["Sáu Thiên Thần ngoại giới"],"nguon":["@c0975"]},{"id":"vung-dat-co-xua-co-thanh-nhan-moc","name":"Vùng đất cổ xưa có Thánh Nhân mộc","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một hiểm địa cổ xưa trong Tiên cổ, nơi Thánh Nhân mộc sinh trưởng.","detail":"Thạch Hạo rời Hồn đảo và tới vùng đất này để tìm Thánh Nhân mộc, chuẩn bị cho con đường đột phá cực cảnh. Khu vực có ác thú và độc trùng canh giữ thần mộc.","theLucLienQuan":[],"nguon":["@c0977"]},{"id":"khu-co-dia-thanh-nhan-moc","name":"Khu cổ địa Thánh Nhân mộc","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Khu cổ địa có rừng gồm bốn mươi chín cây Thánh Nhân mộc, hiện bị Ninh Xuyên chiếm để bế quan.","detail":"Khu rừng nằm sâu trong dãy núi Tiên cổ, có linh khí nồng đậm và bốn mươi chín cây Thánh Nhân mộc. Quanh vùng tồn tại hung cầm cấp Thiên Thần đã phát điên cùng một con trâu hoang cấp Giáo chủ đang ngủ say. Ninh Xuyên bế quan tại đây dưới sự bảo vệ của Mã Dược và Ma Lạc.","theLucLienQuan":["Nhân Mã tộc","Cổ Ma tộc"],"nguon":["@c0978"]},{"id":"tuyet-dia-rung-da","name":"Tuyệt địa rừng đá","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Tuyệt địa có trường vực giam cầm pháp lực và rừng gồm mấy trăm cây Thánh Nhân mộc nằm sâu bên trong.","detail":"Trường vực trong rừng đá khiến người tiến vào mất pháp lực và bị đánh rơi xuống trạng thái như phàm nhân. Nơi đây có kiến thần đen khổng lồ, rết có cánh kịch độc cùng hàng chục bộ lạc trùng tộc điên loạn. Sau khi vượt qua các hiểm họa với sự trợ giúp của Hoàng điệp, Thạch Hạo tìm thấy một rừng Thánh Nhân mộc gồm mấy trăm cây, mỗi cây cao hơn người và tỏa hào quang rực rỡ.","theLucLienQuan":[],"nguon":["@c0978"]},{"id":"rung-thanh-nhan-moc","name":"Rừng Thánh Nhân mộc","cn":"","capDo":"khac","parentId":"khu-co-dia-thanh-nhan-moc","blurb":"Khu rừng cổ thụ Thánh Nhân mộc có khí lành lan tỏa và là sào huyệt của bộ lạc chồn tím.","detail":"Bên trong khu rừng, pháp lực có thể sử dụng trở lại, khác với vùng bên ngoài nơi pháp lực biến mất. Rừng có nhiều Thánh Nhân mộc cổ thụ cao hơn người trưởng thành, đồng thời ẩn chứa ba Thiên Thần chồn tím điên và một con chồn già cấp Giáo chủ.","theLucLienQuan":["Bộ lạc chồn tím"],"nguon":["@c0979"]},{"id":"dam-lay-chua-tan-tran-co","name":"Đầm lầy chứa tàn trận cổ","cn":"","capDo":"khac","parentId":"khu-co-dia-thanh-nhan-moc","blurb":"Đầm lầy trong cổ địa che giấu một tàn trận có từ hơn một kỷ nguyên trước.","detail":"Khi mặt đầm lầy nứt ra, tàn trận phát gợn sóng thần bí bao phủ cổ địa theo chu kỳ tựa thủy triều. Gợn sóng khiến sinh linh trầm miên nhưng không tác động đến nham thạch.","theLucLienQuan":[],"nguon":["@c0979"]},{"id":"tuyet-dia-khu-co-dia","name":"Tuyệt địa","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Khu cổ địa nguy hiểm được tàn trận bảo vệ, bên trong có đầm lầy, rừng Thánh Nhân mộc và chồn tím cấp Giáo chủ. Ngay cả Thiên Thần cũng khó công phá trực tiếp.","detail":"Đầm lầy trong tuyệt địa định kỳ nứt ra và phát phù văn, mở lối tới rừng gồm hàng trăm cây Thánh Nhân mộc. Tàn trận cổ có thể chặn ngọn núi do Thiên Thần luyện hóa ném vào, còn vụ nổ trong khu vực từng đánh thức chồn tím cấp Giáo chủ cư trú tại đây.","theLucLienQuan":["Tiên điện","Minh tộc","Ma Quỳ viên"],"nguon":["@c0980"]},{"id":"con-duong-chin-doan","name":"Con đường chín đoạn","cn":"","aliases":["Con đường Trường sinh"],"capDo":"khac","parentId":"tuyet-dia-khu-co-dia","blurb":"Con đường đá cổ xuyên qua hư không và bị chặt đứt thành chín đoạn nguy hiểm.","detail":"Giữa các đoạn đứt là khoảng trống phóng ra huyết quang và tia chớp đen, đủ sức hủy diệt cốt khí Chân Thần. Người vượt đường phải chịu chín lần xung kích dữ dội; trên mặt đường có hai dòng chữ bằng máu ghi tên Con đường chín đoạn và Con đường Trường sinh. Điểm cuối dẫn vào một nhà đá kín.","theLucLienQuan":[],"nguon":["@c0981"]},{"id":"nha-da-kin","name":"Nhà đá kín","cn":"","aliases":["Nhà đá cuối Con đường chín đoạn"],"capDo":"khac","parentId":"con-duong-chin-doan","blurb":"Không gian kín hình thành khi những vách đá ở cuối Con đường chín đoạn ép lại từ bốn phía.","detail":"Bên trong tràn ngập khí hỗn độn, trên vách có tám chữ cổ mang nghĩa đánh phá thiên địa để nhìn thấy Trường sinh. Hơn mười thi thể không hồn nhưng còn sinh cơ được giấu trong vách đá, sau lưng đều có vết rách tỏa thánh quang giống dấu tích lột xác thành Tiên.","theLucLienQuan":[],"nguon":["@c0981"]},{"id":"vach-da-cuoi-con-duong-co","name":"Vách đá cuối con đường cổ","cn":"","capDo":"khac","parentId":"con-duong-chin-doan","blurb":"Vách đá nằm ở điểm cuối con đường cổ, ngăn cách với một không gian có khí tức tương tự Linh giới và Hư Thần giới.","detail":"Sau tám đòn đánh của Thạch Hạo, vách đá nứt ra và phát sinh lực hút mạnh nhằm kéo nguyên thần rời khỏi thể xác. Phía bên kia tràn ra ánh sáng vàng, mưa ánh sáng và cánh hoa, cùng khí tức giống Linh giới nhưng nồng đậm hơn vô số lần. Khi Thạch Hạo trấn áp nguyên thần thành công, vách đá khôi phục trạng thái ban đầu.","theLucLienQuan":[],"nguon":["@c0982"]},{"id":"khu-rung-thanh-nhan-moc","name":"Khu rừng Thánh Nhân mộc","cn":"","capDo":"khac","parentId":"rung-thanh-nhan-moc","blurb":"Khu vực trong rừng Thánh Nhân mộc nơi Thạch Hạo trở về bế quan và tiến hành Thánh tế.","detail":"Thánh Nhân mộc tại đây phát sáng như lửa thần và bao phủ Thạch Hạo trong thời gian hắn bế quan. Hắn trải qua mười lần tế luyện thân thể tại khu rừng và cuối cùng hoàn thành Thánh tế dù liên tục bị các thế lực bên ngoài quấy phá.","theLucLienQuan":["Thiên Hồ tộc","Minh tộc","Ma Quỳ viên","Tiên điện"],"nguon":["@c0982"]},{"id":"co-dia-be-quan-cua-ninh-xuyen","name":"Cổ địa bế quan của Ninh Xuyên","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Cổ địa từng được Ninh Xuyên dùng để bế quan và tiến hành Thánh tế.","detail":"Nơi này có mấy chục cây Thánh Nhân mộc. Khi Thạch Hạo tìm tới, cây cối đã gần khô héo và Ninh Xuyên đã rời đi, cho thấy hắn có khả năng hoàn thành Thánh tế.","theLucLienQuan":[],"nguon":["@c0984"]},{"id":"tang-thu-tam-than-vuong-kiep","name":"Tầng thứ tám Thần vương kiếp","cn":"","capDo":"khac","parentId":null,"blurb":"Tầng kiếp có núi non, rừng cổ thụ và một tòa thành khổng lồ đều do lôi đình hóa thành. Lò xương sọ bên trong thành có thể tập trung toàn bộ lôi đình của tầng này để luyện hóa người độ kiếp.","detail":"Tòa thành cổ đóng kín, tường thành loang lổ dấu kiếm đao và mang khí tức tang thương. Xương sọ trắng như ngọc từ trong thành xuất hiện, nuốt Thạch Hạo rồi hóa thành lò luyện, khiến toàn bộ lôi đình tầng thứ tám dung hợp và công kích hắn tại một điểm.","theLucLienQuan":[],"nguon":["@c0989"]},{"id":"tang-thu-chin-than-vuong-kiep","name":"Tầng thứ chín Thần vương kiếp","cn":"","capDo":"khac","parentId":null,"blurb":"Tầng kiếp yên tĩnh, lôi đình và các sinh linh thực vật đều không mạnh. Nguy hiểm thực sự nằm ở khả năng ép đạo hạnh của người độ kiếp hạ thấp nghiêm trọng.","detail":"Sau khi Thạch Hạo tiến vào, thiên kiếp ép đạo hạnh của hắn từ mức ngang Thiên Thần xuống Chân Thần rồi Thần Hỏa cảnh, khiến chu kỳ suy yếu của Thánh tế xuất hiện sớm hơn ba ngày. Năm Thiên Thần ngoại giới lợi dụng thời điểm này xông vào lôi đình đánh giết hắn.","theLucLienQuan":["Người ngoại giới","Bát Tí Hồn tộc"],"nguon":["@c0989"]},{"id":"tang-thu-chin-cua-thien-kiep","name":"Tầng thứ chín của thiên kiếp","cn":"","capDo":"khac","parentId":null,"blurb":"Cửa ải thiên kiếp nơi Thạch Hạo bị năm Thiên Thần ngoại giới truy sát rồi phản sát toàn bộ đối phương.","detail":"Tại tầng này, tu vi Thạch Hạo từng rơi xuống Thần Hỏa cảnh khiến hắn lâm vào tử cục. Một kẻ truy sát bị thiên phạt cấp Thiên Thần đánh chết, bốn kẻ còn lại bị Thạch Hạo tiêu diệt sau khi pháp lực của hắn phục hồi về lĩnh vực Thánh tế. Khi cửa ải hoàn tất, lôi kiếp trở nên ôn hòa và con đường lên tầng cuối được mở ra.","theLucLienQuan":[],"nguon":["@c0990"]},{"id":"tang-thu-muoi-cua-thien-kiep","name":"Tầng thứ mười của thiên kiếp","cn":"","capDo":"khac","parentId":null,"blurb":"Tầng cuối của thiên kiếp, mang cảnh tượng như tiên cảnh và có Trảm Tiên đài cùng Tiên trì chứa Lôi Kiếp dịch.","detail":"Nơi đây có cổ mộc, tiên phủ và động phủ lơ lửng, cùng Chân Hoàng, Chân Long, tiên cầm và trường sinh thú do lôi đình diễn hóa. Trảm Tiên đài tỏa sát khí khiến Thạch Hạo phải đi vòng, còn Tiên trì năm màu là nơi hắn nhận được Lôi Kiếp dịch sau khi vượt kiếp thành công.","theLucLienQuan":[],"nguon":["@c0990"]},{"id":"tien-tri","name":"Tiên trì","cn":"","capDo":"khac","parentId":"tang-thu-muoi-cua-thien-kiep","blurb":"Ao cổ phát ánh sáng năm màu tại tầng thứ mười của thiên kiếp, chứa Lôi Kiếp dịch.","detail":"Tiên trì rộng vài thước vuông, có sương mù và khí hỗn độn bao phủ. Nơi này xua tan nguyền rủa và chứa Lôi Kiếp dịch năm màu, giúp Thạch Hạo quét sạch ám thương, bù đắp nguyên khí sau khi hoàn thành thiên kiếp.","theLucLienQuan":[],"nguon":["@c0990"]},{"id":"co-dia-ngan-huyet-ma-thu-toc","name":"Cổ địa Ngân Huyết ma thụ tộc","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Lãnh địa của Ngân Huyết ma thụ tộc trong Tiên cổ, gồm những dãy núi phủ ánh bạc, cung điện và các đảo lơ lửng.","detail":"Nhiều Ngân Huyết ma thụ sinh sống trong khu cổ địa này. Thạch Hạo mang lôi hải vượt hư không tới đây, công kích một sinh linh để kích thích thiên kiếp bạo động và khiến lôi điện đánh xuống lãnh địa.","theLucLienQuan":["Ngân Huyết ma thụ tộc"],"nguon":["@c0991"]},{"id":"hoang-mac-tien-co","name":"Hoang mạc Tiên cổ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một vùng hoang mạc trong Tiên cổ, nơi các Giáo chủ giao chiến dữ dội.","detail":"Trận quyết chiến giữa các Giáo chủ tại đây gây nên cảnh tượng trời long đất lở và trở thành một phần của bão táp do cuộc tranh đoạt Lôi Kiếp dịch.","theLucLienQuan":["Bát Tí Hồn tộc"],"nguon":["@c0993"]},{"id":"mat-dia-co-thien-than-thu","name":"Mật địa có Thiên Thần thụ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một mật địa có hư không bất ổn và ẩn chứa Thiên Thần thụ.","detail":"Tu sĩ ở bất kỳ cảnh giới nào tiến vào khu vực này cũng có thể gặp nguy hiểm. Chính mức độ hiểm trở có khả năng cản bước Giáo chủ cùng tạo hóa bên trong khiến Thạch Hạo quyết định thăm dò.","theLucLienQuan":[],"nguon":["@c0993"]},{"id":"dong-phu-tien-gia","name":"Động phủ tiên gia","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một hiểm địa chứa tạo hóa trong Tiên cổ.","detail":"Đây là một trong những địa điểm được các Giáo chủ tiết lộ cho Thạch Hạo. Sự nguy hiểm của động phủ có thể cản bước Giáo chủ, khiến hắn muốn tới thăm dò trước khi rời Tiên cổ.","theLucLienQuan":[],"nguon":["@c0993"]},{"id":"co-dia-thien-than-thu","name":"Cổ địa Thiên Thần thụ","cn":"","capDo":"khac","parentId":"tien-co","blurb":"Một cổ địa nguy hiểm nằm sau sa mạc bão cát và vùng hư không bất ổn, là nơi Thiên Thần thụ cổ xưa sinh trưởng.","detail":"Đường vào cổ địa đi qua sa mạc bão cát, những vết nứt hư không, hỏa tinh Thái dương và khu vực lôi điện mang thuộc tính thiên kiếp. Nhiều bột xương Thiên Thần nằm dọc đường, còn Thiên Thần thụ mọc trên đỉnh một ngọn núi cao ở sâu bên trong.","theLucLienQuan":[],"nguon":["@c0994"]},{"id":"vung-loi-kiep-sau-trong-co-dia","name":"Vùng lôi kiếp sâu trong cổ địa","cn":"","capDo":"khac","parentId":"co-dia-thien-than-thu","blurb":"Khu vực nguy hiểm nằm sâu trong cổ địa, tràn ngập lôi đình và những sinh linh do điện quang hóa thành.","detail":"Hàng vạn tia chớp mạnh bao phủ khu vực này, đến Thiên Thần thụ cũng không dám xông vào. Thạch Hạo phải vượt qua nơi đây để tìm Vạn Vật thổ.","theLucLienQuan":[],"nguon":["@c0995"]},{"id":"cau-vom-bang-da","name":"Cầu vòm bằng đá","cn":"","capDo":"khac","parentId":"vung-loi-kiep-sau-trong-co-dia","blurb":"Cây cầu đá dẫn vào vùng tinh thổ thần bí nằm giữa lôi đình.","detail":"Khi Thạch Hạo bước lên cầu, lôi đình lập tức giáng xuống khiến toàn thân hắn cháy đen, nhưng hắn vẫn vượt qua để tiến vào khu vực có Vạn Vật thổ.","theLucLienQuan":[],"nguon":["@c0995"]},{"id":"vung-tinh-tho-chua-van-vat-tho","name":"Vùng tịnh thổ chứa Vạn Vật thổ","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng tịnh thổ có nhiều cổ dược, thánh dược và một lớp Vạn Vật thổ chôn giấu nhiều bí mật.","detail":"Thạch Hạo tìm thấy chân thân Ma nữ đang bế quan trong Vạn Vật thổ tại đây. Bên dưới nàng còn có một sinh linh chưa rõ danh tính và Thiên địa mẫu khí đỉnh, trong khi một sức mạnh kỳ dị giữ lại phần thần thổ ở tầng sâu.","theLucLienQuan":[],"nguon":["@c0996"]},{"id":"khu-vuc-duoi-van-vat-tho","name":"Khu vực dưới Vạn Vật thổ","cn":"","capDo":"khac","parentId":"vung-tinh-tho-chua-van-vat-tho","blurb":"Khu vực nằm dưới lớp Vạn Vật thổ, nơi chôn chiến y của Nữ Tiên vô danh và giọt Đế huyết từng bám trên Thiên địa mẫu khí đỉnh.","detail":"Lớp Vạn Vật thổ tại đây rộng khoảng một trượng vuông và sâu khoảng một trượng. Chiến y nứt vỡ nằm trong thần thổ, còn giọt Đế huyết được phát hiện dưới đáy.","theLucLienQuan":[],"nguon":["@c0997"]},{"id":"bien-hoang","name":"Biên Hoang","cn":"","capDo":"vuc","parentId":null,"blurb":"Một khu vực được Thiên Thần trẻ tuổi của nhóm khách thần bí nhắc tới khi chế giễu thực lực của ba ngàn châu.","detail":"Vị khách trẻ tuổi cho rằng các Thiên Thần ba ngàn châu hiện tại quá yếu, không đủ sức trấn thủ Biên Hoang.","theLucLienQuan":["Nhóm khách thần bí ngoài ba ngàn châu"],"nguon":["@c0998"]},{"id":"cuu-thien-thap-dia","name":"Cửu thiên Thập địa","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Không gian rộng lớn xuất hiện trong dấu ấn do giọt Đế huyết lưu lại.","detail":"Trong cảnh tượng vượt thời gian, Cửu thiên Thập địa nhuốm máu, thần ma bỏ mạng và nhiều bóng người chém giết giữa một cuộc đại chiến đáng sợ.","theLucLienQuan":[],"nguon":["@c0998"]},{"id":"thuong-chau","name":"Thương châu","cn":"","capDo":"chau","parentId":"ba-ngan-chau","blurb":"Một châu thuộc Ba ngàn đạo châu, nơi Kiếm vương Mục Thiết giao chiến với khách vực ngoại.","detail":"Kiếm quang do Mục Thiết phát ra chiếu rọi Thương châu và khiến các cao thủ toàn châu cảm ứng. Ông bị khách vực ngoại đánh bại tại đây.","theLucLienQuan":[],"nguon":["@c0999"]},{"id":"tieu-thien-the-gioi-noi-ninh-xuyen-do-kiep","name":"Tiểu thiên thế giới nơi Ninh Xuyên độ kiếp","cn":"","capDo":"gioi-nho","parentId":"di-dia-tien-co","blurb":"Tiểu thiên thế giới nơi Ninh Xuyên dẫn phát thiên kiếp dưới sự bảo vệ của phe Ngân Huyết ma thụ.","detail":"Thạch Hạo cùng các Giáo chủ phe mình xông vào khu vực này để tập kích Ninh Xuyên và tranh đoạt Lôi Kiếp dịch.","theLucLienQuan":["Phe Ngân Huyết ma thụ","Phe Giáo chủ của Thạch Hạo"],"nguon":["@c1000"]},{"id":"loi-ra-tien-co","name":"Lối ra Tiên cổ","cn":"","capDo":"khac","parentId":"di-dia-tien-co","blurb":"Lối rời khỏi Tiên cổ đang được lực lượng của Thạch Hạo canh giữ.","detail":"Linh thân Giáo chủ tọa trấn tại đây khiến Ninh Xuyên không thể rời khỏi Tiên cổ trước khi độ kiếp.","theLucLienQuan":["Phe Giáo chủ của Thạch Hạo"],"nguon":["@c1000"]}]};
